+// RF-004: descuento opcional por línea (porcentaje 0–100), aplicado antes del total y redondeado al centavo.
+function totalLinea({ cantidad, precioUnitarioCentavos, descuentoPct = 0 }) {
+  if (typeof descuentoPct !== "number" || !(descuentoPct >= 0 && descuentoPct <= 100))
+    throw new RangeError("Descuento inválido: debe estar entre 0 y 100");
+  return Math.round((cantidad * precioUnitarioCentavos * (100 - descuentoPct)) / 100);
+}
