diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..c9ff993 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,29 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+test("RF-004: descuento por línea antes del total, redondeado al centavo", () => {
+  const f = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPct: 10 }]);
+  assert.equal(f.totalCentavos, 1800);
+  // sin descuento (o 0 %) no cambia nada
+  assert.equal(calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPct: 0 }]).totalCentavos, 2000);
+  // 100 % deja la línea en 0
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPct: 100 }]).totalCentavos, 0);
+  // redondeo al centavo: 333 con 10 % = 299,7 → 300
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 333, descuentoPct: 10 }]).totalCentavos, 300);
+  // el descuento se aplica por línea
+  const g = calcularFactura([
+    { cantidad: 2, precioUnitarioCentavos: 1000, descuentoPct: 10 },
+    { cantidad: 1, precioUnitarioCentavos: 500 },
+  ]);
+  assert.equal(g.totalCentavos, 2300);
+});
+
+test("RF-004: un descuento fuera de 0–100 se rechaza", () => {
+  for (const descuentoPct of [-1, 100.5, 101, NaN, "10"]) {
+    assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPct }]), RangeError);
+  }
+});
